{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list) or len(nodes) == 0:
        raise ValueError("Invalid or empty nodes")
    if not isinstance(core_distance, dict):
        raise ValueError("Invalid core_distance")
    if not isinstance(distances, list):
        raise ValueError("Invalid distances")
    for node in nodes:
        if node not in core_distance:
            raise ValueError(f"Missing core_distance for node {node}")

    n = len(nodes)

    mr_edges = []
    for edge in distances:
        u, v, dist = edge[0], edge[1], edge[2]
        cd_u = core_distance[u]
        cd_v = core_distance[v]
        mr_weight = max(cd_u, cd_v, dist)
        # canonicalize: lexicographically smaller first
        a, b = (u, v) if u <= v else (v, u)
        mr_edges.append((mr_weight, a, b))

    # deterministic sort: by weight, then first endpoint, then second endpoint
    mr_edges.sort(key=lambda e: (e[0], e[1], e[2]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        # path compression
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for mr_weight, a, b in mr_edges:
        if union(a, b):
            mst_edges.append([a, b, mr_weight])
            total_weight += mr_weight
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError("Graph is disconnected; MST cannot span all nodes")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
"}
